-- Agent One HR Analytics Demo Database
-- Synthetic data for testing Text2SQL and multi-table business questions.

BEGIN TRANSACTION;
CREATE TABLE attendance(
 attendance_id INTEGER PRIMARY KEY, employee_id INTEGER NOT NULL,
 attendance_date DATE NOT NULL, check_in TIME, check_out TIME,
 status TEXT NOT NULL, late_flag INTEGER NOT NULL, compliance_flag INTEGER NOT NULL,
 working_hours REAL, FOREIGN KEY(employee_id) REFERENCES employees(employee_id),
 UNIQUE(employee_id,attendance_date)
);
