CREATE TABLE employees(
 employee_id INTEGER PRIMARY KEY, company_id INTEGER NOT NULL,
 department_id INTEGER NOT NULL, manager_id INTEGER,
 first_name TEXT NOT NULL, last_name TEXT NOT NULL, email TEXT UNIQUE NOT NULL,
 job_title TEXT NOT NULL, employment_type TEXT NOT NULL,
 hire_date DATE NOT NULL, salary REAL NOT NULL,
 status TEXT NOT NULL,
 FOREIGN KEY(company_id) REFERENCES companies(company_id),
 FOREIGN KEY(department_id) REFERENCES departments(department_id),
 FOREIGN KEY(manager_id) REFERENCES employees(employee_id)
);
