CREATE TABLE payroll(
 payroll_id INTEGER PRIMARY KEY, employee_id INTEGER NOT NULL,
 payroll_month DATE NOT NULL, base_salary REAL NOT NULL,
 overtime_pay REAL NOT NULL, deductions REAL NOT NULL, bonus REAL NOT NULL,
 net_salary REAL NOT NULL, FOREIGN KEY(employee_id) REFERENCES employees(employee_id),
 UNIQUE(employee_id,payroll_month)
);
