CREATE TABLE projects(
 project_id INTEGER PRIMARY KEY, company_id INTEGER NOT NULL,
 project_name TEXT NOT NULL, client_name TEXT, start_date DATE NOT NULL,
 end_date DATE, budget REAL NOT NULL, status TEXT NOT NULL,
 FOREIGN KEY(company_id) REFERENCES companies(company_id)
);
